+    line: usize,
+    namespace: Namespace,
+    import: bool,
+}
+
+fn query_error(pattern: &LedgerPattern, site: &Site<'_>, source: CodeResolveError) -> Error {
+    Error::CodePath {
+        pattern: pattern.id.clone(),
+        file: site.file.path.to_string(),
+        line: site.line,
+        source: Box::new(source),
+    }
+}
